def trig():
    return {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
def write_all(preds, expected):
    ids=[p["case_id"] for p in preds]
    assert ids==expected, (ids, expected)
    for p in preds:
        assert set(p.keys())=={"case_id","prediction_text","basis","confidence","trigger"}, p["case_id"]
        assert 0 <= p["confidence"] <= 1
        with open(os.path.join(BASE, p["case_id"]+".json"), "w", encoding="utf-8") as f:
            json.dump(p, f, ensure_ascii=False, indent=1)
    #逐件精确回读自验
    for cid in expected:
        with open(os.path.join(BASE, cid+".json"), encoding="utf-8") as f:
            d=json.load(f)
        assert d["case_id"]==cid and d["prediction_text"] and d["basis"]
    print("OK", len(expected), expected[0], expected[-1])

